  end
  function self:initialize()
    self:stop("Initializing")
    local cleared,errors=self:clearAll()
    if not cleared then self:fail(table.concat(errors,"; ")); return false,self.fault end
    for i=1,9 do
      local e=self.engines[i]
      if not api.peripheral.hasType(e.name,"creative_vector_thruster") then self:fail("Missing/wrong type: "..e.name); break end
      local ok,limit=pcall(api.peripheral.call,e.name,"getMaxThrustOutputPn")
      if not ok or not finite(limit) or limit<self.caps[i]*1000 then self:fail("Invalid/insufficient cap: "..e.name); break end
    end
    self.ready=not self.fault
    return self.ready,self.fault
  end
  function self:arm()
    if not self.ready or self.fault then return false,"Backend not ready" end
    for _,e in ipairs(self.engines) do
      if e.gate~=0 or e.output~=0 or e.x~=0 or e.y~=0 or api.clock()-e.lastAck>.25 then return false,"Await fresh zero acknowledgements" end
    end
    self.epoch=self.epoch+1; self.armed=true; self.lastInput=api.clock()
    return true
  end
  function self:submit(commands)
    if not self.armed or self.fault then return false,"Not armed" end
    local ok,copy=pcall(function()
      assert(type(commands)=="table" and #commands==9,"Need exactly nine commands")
      local result={}
      for i=1,9 do
        local c=commands[i]; assert(type(c)=="table" and c.name==name(i),"Engine order/identity mismatch")
        assert(finite(c.kn) and c.kn>=0 and c.kn<=self.caps[i],"Power outside configured cap")
        for _,v in ipairs({c.vectorX,c.vectorY}) do
          assert(finite(v) and math.abs(v)<=.2+1e-9 and math.abs(v*15-math.floor(v*15+.5))<1e-7,"Invalid/non-quantized vector")
        end
        assert(finite(c.vectorX) and finite(c.vectorY),"Missing vector")
        if i>5 then assert(c.vectorX==0 and c.vectorY==0,"Top vectoring not supported") end
        result[i]={kn=c.kn,vectorX=c.vectorX,vectorY=c.vectorY}
      end
      return result
    end)
    if not ok then self:fail("Invalid frame: "..tostring(copy)); return false,self.fault end
    for i=1,9 do
      if copy[i].kn==0 and self.desired[i].kn>0 then self.engines[i].generation=self.engines[i].generation+1 end
    end
    self.desired=copy; self.lastInput=api.clock(); return true
  end
  function self:cycle(i)
    local e=self.engines[i]; local s=self.desired[i]
    local epoch,generation=self.epoch,e.generation
    local function valid()
      return self.armed and not self.fault and self.epoch==epoch and e.generation==generation and
        self.desired[i].kn>0 and api.clock()-self.lastInput<=.35
    end
    local complete=true
    local function send(method,...)
      local ok,err=pcall(api.peripheral.call,e.name,method,...)
      if not ok then complete=false; self:fail(e.name.." "..method..": "..tostring(err)) end
      return ok
    end
    if s.kn==0 or not valid() then
      -- Independent attempts even if gate-off fails. Retain zero base override.
      if e.gate~=0 and send("setThrust",0) then e.gate=0 end
      if e.output~=0 and send("setThrustOutput",0) then e.output=0 end
      if (e.x~=0 or e.y~=0) and send("setVector",0,0) then e.x,e.y=0,0 end
    else
      local output=s.kn*1000
      if e.output~=output and send("setThrustOutput",output) then e.output=output end
      if complete and valid() and (e.x~=s.vectorX or e.y~=s.vectorY) and send("setVector",s.vectorX,s.vectorY) then e.x,e.y=s.vectorX,s.vectorY end
      if complete and valid() and e.gate~=15 and send("setThrust",15) then e.gate=15 end
    end
    if complete and epoch==self.epoch and generation==e.generation then e.lastAck=api.clock() end
  end
  function self:watchdog()
    if not self.armed then return end
    if api.clock()-self.lastInput>.35 then self:fail("Command stream stale >0.35s"); return end
    for _,e in ipairs(self.engines) do
      if not api.peripheral.hasType(e.name,"creative_vector_thruster") then self:fail("Disconnected: "..e.name); return end
      if api.clock()-e.lastAck>.6 then self:fail("Output timeout: "..e.name); return end
    end
  end
  function self:run(producer)
    assert(self.ready,"Initialize before run")
    self.running=true
    local tasks={function()
      local ok,err=pcall(producer,self)
      if not ok then self:fail("Producer: "..tostring(err)) end
      self:stop("Producer finished"); self.running=false
    end,function() while self.running do self:watchdog(); api.sleep(.05) end end}
    for i=1,9 do local index=i; tasks[#tasks+1]=function()
      while self.running do self:cycle(index); api.sleep(.05) end
    end end
    -- Drain in-flight calls before final cleanup: do not cancel coroutines and
    -- let their already-queued positive writes complete after the final zeros.
    api.parallel.waitForAll(table.unpack(tasks))
    return self:clearAll()
  end
  return self
end
return M

end
factories["flight_session"]=function(...)
-- Operator state machine. Initialization/worker lifetime belongs to the app.
local M={version=1}
local function finite(n) return type(n)=="number" and n==n and math.abs(n)<math.huge end
function M.new(deps,driver,config)
  local valid,why=deps.planner.validate(config.profile); assert(valid,why)
  assert(config.craft.id==config.profile.craftId,"Geometry identity mismatch")
  assert(type(config.caps)=="table" and #config.caps==9,"Nine explicit engine limits required")
  for i=1,9 do
    local cap=i<=5 and config.limits.mainKN or config.limits.topKN[i-5]
    assert(finite(cap) and cap>=0 and cap<=config.caps[i],"Allocation/output cap mismatch")
  end
  local self={mode="DISARMED",throttle=0,driver=driver,config=config}
  local function checked(s,now)
    assert(s and finite(s.time) and finite(now) and now>=s.time and now-s.time<=.25,"Fresh telemetry required")
    assert(s.craftId==config.profile.craftId and finite(s.mass) and math.abs(s.mass/config.profile.mass-1)<=.02,"Craft/profile mismatch")
    assert(s.allNineReady==true,"Nine output links required")
    assert(finite(s.tilt) and s.tilt<math.rad(10) and finite(s.angularSpeed) and s.angularSpeed<.15,"Attitude outside envelope")
  end
  function self:stop(reason)
    driver:stop(reason); self.mode="DISARMED"; self.throttle=0; self.runtime=nil
    self.hover=nil; self.previous=nil; self.balance=nil; self.output=nil; self.message=reason
  end
  function self:action(action,s,now)
    if action=="stop" then self:stop("Operator stop"); return true end
    local ok,err=pcall(function()
      checked(s,now)
      if action=="pad" then
        assert(self.mode=="DISARMED","Record pad only disarmed and supported")
        assert(s.tilt<math.rad(3) and math.abs(s.vy)<.05 and s.vx^2+s.vz^2<.0025,"Pad requires still upright craft")
        -- Operator must ensure supported: this is not a contact sensor.
        self.pad={x=s.x,y=s.y,z=s.z}; self.message="Pad recorded in memory"
      elseif action=="arm" then
        assert(self.mode=="DISARMED" and self.pad,"Record pad first")
        assert(s.tilt<math.rad(3) and math.abs(s.vy)<.1 and s.vx^2+s.vz^2<.01,"Arm requires still upright craft")
        local ready,why=driver:arm(); assert(ready,why)
        self.mode="MANUAL"; self.throttle=0; self.lastTime=now
      elseif action=="up" or action=="down" then
        assert(self.mode=="MANUAL","Throttle keys require MANUAL")
        self.throttle=math.max(0,math.min(config.profile.maxThrottle,self.throttle+(action=="up" and .01 or -.01)))
      elseif action=="hover" then
        assert(driver.armed,"Arm first")
        self.hover=deps.hover.start(config.profile,{x=s.x,y=s.y-20,z=s.z},now)
        self.mode="HOVER"; self.balance=nil; self.lastTime=now
      elseif action=="descent" or action=="boostback" then
        assert(driver.armed and self.pad,"Need armed craft and pad")
        local state,why=deps.runtime.start(deps,driver,config.profile,self.pad,s,now,
          config.craft,config.limits,"live",action)
        assert(state,why); self.runtime=state; self.mode="MISSION"; self.lastTime=now
      else error("Unsupported action") end
    end)
    if not ok then self.message=tostring(err); return false,self.message end
    return true
  end
  function self:tick(s,now)
    if self.mode=="DISARMED" then return nil end
    local ok,out=pcall(function()
      checked(s,now); assert(driver.armed and not driver.fault,"Output backend stopped")
      if self.mode=="MISSION" then return deps.runtime.step(deps,self.runtime,s,now) end
      local lim={}; for k,v in pairs(config.limits) do lim[k]=v end
      lim.previous=self.previous; lim.balance=self.balance; lim.dt=now-self.lastTime
      assert(lim.dt>0 and lim.dt<=.25,"Control interval invalid")
      local result
      if self.mode=="MANUAL" and self.throttle==0 then
        local commands={}
        for i=0,8 do commands[#commands+1]={name="creative_vector_thruster_"..i,kn=0,vectorX=0,vectorY=0} end
        self.balance=nil; self.previous=nil
        result={commands=commands,plan={phase="MANUAL",mainThrottle=0}}
      elseif self.mode=="HOVER" then result=deps.hover.step(deps,self.hover,s,now,config.craft,lim)
      else
        result=deps.control.step(deps,{profile=config.profile},s,now,config.craft,lim,
          {phase="MANUAL",mainThrottle=self.throttle,lateral={ax=0,az=0},shadowOnly=true})
      end
      if result.commands then
        local sent,why=driver:submit(result.commands); assert(sent,why)
      end
      return result
    end)
    self.lastTime=now
    if not ok or not out or out.manualTakeover or not out.commands then
      self:stop(not ok and tostring(out) or (out and out.error) or "Guidance unavailable")
      return nil,self.message -- Explicit emergency cutoff, NOT safe landing.
    end
    if out.allocation then self.previous={x=out.allocation.mainX,y=out.allocation.mainY}; self.balance=out.allocation.balance end
    self.output=out; return out
  end
  return self
end
return M

end
factories["console_view"]=function(...)
-- Terminal rendering and mouse hit-testing only; never controls engines.
local M={version=1}
function M.draw(term,colors,state)
  local width,height=term.getSize(); local buttons={}
  term.setBackgroundColor(colors.black); term.setTextColor(colors.white); term.clear()
  local function line(y,text,color)
    if y>height then return end
    term.setCursorPos(1,y); term.setTextColor(color or colors.white); term.write(text:sub(1,width))
  end
  line(1,"ROCKET | "..(state.live and state.mode or "READ ONLY"),colors.cyan)
  if width<30 or height<16 then
    line(2,"Screen too small: need 30x16",colors.orange)
    line(3,"SPACE stops | Q exits",colors.red)
    return buttons
  end
  line(2,"RETURN > COAST > BRAKE > HOVER")
  local s=state.sample
  if s then
    line(3,("Y %.2f Vy %+.2f Tilt %.1f"):format(s.y,s.vy,math.deg(s.tilt)))
    line(4,("Read %.3fs | links %s"):format(s.acquisitionSeconds,s.allNineReady and "ACK OK" or "NOT READY"))
  else line(3,"Telemetry unavailable",colors.orange) end
  local out=state.output
  line(5,"Phase: "..(out and out.plan and out.plan.phase or "--"))
  local kn=out and out.commands and out.commands[1].kn or 0
  line(6,("Main request %.1f%% | pad %s"):format(kn/733*100,state.pad and "SET" or "--"))
  local split=math.floor(width/2)
  local function button(row,col,label,action,danger)
    local x=col==1 and 1 or split+1; local w=col==1 and split or width-split
    term.setCursorPos(x,row)
    term.setBackgroundColor(danger and colors.red or (colors.gray or colors.black))
    term.setTextColor(colors.white)
    term.write((label..string.rep(" ",w)):sub(1,w))
    term.setBackgroundColor(colors.black)
    buttons[#buttons+1]={x=x,y=row,width=w,action=action}
  end
  button(8,1,"J PAD (supported)","pad"); button(8,2,"E ARM ZERO","arm")
  button(9,1,"R +1%","up"); button(9,2,"F -1%","down")
  button(10,1,"V HOVER HERE","hover"); button(10,2,"D DESCENT RETURN","descent")
  button(11,1,"B BOOSTBACK RETURN","boostback")
  button(12,1,"SPACE CUTOFF","stop",true); button(12,2,"Q EXIT","exit",true)
  line(13,"No upper stage / tower hardware",colors.orange)
  line(14,state.live and "Cutoff is NOT a safe landing" or "READ ONLY: controls disabled",colors.orange)
  line(height,state.message or "",colors.yellow)
  return buttons
end
function M.hit(buttons,x,y)
  for _,b in ipairs(buttons) do
    if y==b.y and x>=b.x and x<b.x+b.width then return b.action end
  end
end
return M

end
factories["home_math"]=function(...)
-- v0.5.5 short calibration probes with measured-response braking.
-- Return holds current altitude. No terrain sensing, auto-landing or tower catch.
-- One controller only. Remove old redstone inputs before using this backend.
-- IMPORTANT: this build quantizes setThrustNormalized into 15 steps internally.
-- Use setThrustOutput (unquantized base force) + setThrust(15/0) instead.
-- setVector is also rounded to 1/15 steps by the installed mod; do not fake precision.
local args = {...}
local M = {}
local FULL_THRUST_KN=733 -- User-confirmed per-engine full-scale base thrust.
local UNITS_PER_KN=1000 -- Verified createpropulsion-common.toml, physics section.
local ENGINE_NAMES={}
for i=0,4 do ENGINE_NAMES[#ENGINE_NAMES+1]="creative_vector_thruster_"..i end
local function finite(x) return type(x)=="number" and x==x and math.abs(x)<math.huge end
local function clamp(x,a,b) return math.max(a,math.min(b,x)) end
local function vec(x,y,z) return {x=x,y=y,z=z} end
local function add(a,b) return vec(a.x+b.x,a.y+b.y,a.z+b.z) end
local function mul(a,s) return vec(a.x*s,a.y*s,a.z*s) end
local function dot(a,b) return a.x*b.x+a.y*b.y+a.z*b.z end
local function cross(a,b) return vec(a.y*b.z-a.z*b.y,a.z*b.x-a.x*b.z,a.x*b.y-a.y*b.x) end
local function norm(a) return math.sqrt(dot(a,a)) end
local function unit(a) local n=norm(a); assert(n>1e-9,"Zero vector"); return mul(a,1/n) end
local function checked(v)
  assert(type(v)=="table" and finite(v.x) and finite(v.y) and finite(v.z),"Invalid vector")
  return vec(v.x,v.y,v.z)
end
function M.padDistance(pad,position)
  checked(pad); checked(position)
  return math.sqrt((pad.x-position.x)^2+(pad.z-position.z)^2)
end
function M.quaternion(q)
  assert(type(q)=="table","Missing orientation")
  local v=q.v or q
  local w=q.a
  if w==nil then w=q.w end
  v=checked(v); assert(finite(w),"Invalid quaternion")
  local n=math.sqrt(dot(v,v)+w*w)
  assert(finite(n) and n>1e-6,"Invalid quaternion norm")
  return {x=v.x/n,y=v.y/n,z=v.z/n,w=w/n}
end
local function conjugate(q) return {x=-q.x,y=-q.y,z=-q.z,w=q.w} end
local function product(a,b)
  local v=add(add(mul(a,b.w),mul(b,a.w)),cross(a,b))
  return {x=v.x,y=v.y,z=v.z,w=a.w*b.w-dot(a,b)}
end
function M.rotate(q,v)
  local t=mul(cross(q,v),2)
  return add(v,add(mul(t,q.w),cross(q,t)))
end
-- Orientation-difference rate is in body coordinates (rad/s). This avoids
-- assuming a frame or units for a physics backend's angular-velocity API.
function M.rate(previous,current,dt)
  assert(finite(dt) and dt>0,"Invalid sample time")
  local d=product(conjugate(previous),current)
  if d.w<0 then d={x=-d.x,y=-d.y,z=-d.z,w=-d.w} end
  local n=norm(d)
  if n<1e-8 then return vec(0,0,0) end
  return mul(d,2*math.atan2(n,d.w)/(n*dt))
end
function M.basis(q)
  local up=unit(M.rotate(conjugate(q),vec(0,1,0)))
  local seed=math.abs(up.x)<0.8 and vec(1,0,0) or vec(0,0,1)
  local a=unit(add(seed,mul(up,-dot(seed,up))))
  return {up=up,a=a,b=unit(cross(up,a))}
end
function M.error(q,basis,worldUp)
  local target=M.rotate(conjugate(q),worldUp or vec(0,1,0))
  local angle=math.acos(clamp(dot(basis.up,target),-1,1))
  local axis=cross(basis.up,target)
  local n=norm(axis)
  if n<1e-8 then return 0,0,angle end
  axis=mul(axis,angle/n)
  return dot(axis,basis.a),dot(axis,basis.b),angle
end
function M.matrix(columns)
  local a,c=columns[1][1],columns[1][2]
  local b,d=columns[2][1],columns[2][2]
  for _,v in ipairs({a,b,c,d}) do assert(finite(v),"Invalid response") end
  local n1,n2=math.sqrt(a*a+c*c),math.sqrt(b*b+d*d)
  local det=a*d-b*c
  assert(n1>0.02 and n2>0.02,"No useful response: blocked craft or insufficient thrust")
  assert(math.abs(det)/(n1*n2)>0.35,"Axes overlap: check engine orientations")
  return {a=a,b=b,c=c,d=d,det=det}
end
function M.command(matrix,e1,e2,w1,w2,ratio,state,dt)
  state=state or {i1=0,i2=0,u=0,v=0}
  dt=dt or 0.1
  -- Lower bandwidth and anticipatory braking leave margin for server/nozzle lag.
  local x,y=0.65*(e1-0.2*w1)-1.3*w1,0.65*(e2-0.2*w2)-1.3*w2
  -- Small bounded bias compensation reduces the steady error from 1/15 steps.
  if math.abs(e1)<math.rad(8) and math.abs(e2)<math.rad(8) then
    state.i1=clamp(state.i1+0.06*e1*dt,-0.025,0.025)
    state.i2=clamp(state.i2+0.06*e2*dt,-0.025,0.025)
  else state.i1,state.i2=0,0 end
  x,y=x+state.i1,y+state.i2
  local u=(matrix.d*x-matrix.b*y)/matrix.det/ratio
  local v=(-matrix.c*x+matrix.a*y)/matrix.det/ratio
  local function quantize(n,previous,balance)
    n=clamp(n,-2,2)
    if dt<=0 then
      -- Late sample: update coarse proportional/damping correction, but do not
      -- accumulate pulse time or integral through the uncertain interval.
      local rounded=(n<0 and -1 or 1)*math.floor(math.abs(n)+0.5)
      return clamp(rounded,previous-1,previous+1),balance or 0
    end
    -- Integrate fractional demand in step-seconds. A small persistent demand
    -- produces occasional real one-step pulses instead of rounding to zero forever.
    local accumulated=clamp((balance or 0)+n*dt,-2*dt,2*dt)
    local equivalent=accumulated/dt
    local rounded=(equivalent<0 and -1 or 1)*math.floor(math.abs(equivalent)+0.5)
    local output=clamp(rounded,previous-1,previous+1)
    return output,clamp(accumulated-output*dt,-0.2,0.2)
  end
  state.u,state.bu=quantize(u,state.u,state.bu)
  state.v,state.bv=quantize(v,state.v,state.bv)
  return state.u,state.v
end
function M.navigation(target,p,v,state,dt)
  local ex,ez=target.x-p.x,target.z-p.z
  local distance=math.sqrt(ex*ex+ez*ez)
  -- Slow approach, earlier braking near the target. No integral during transit.
  local speed=math.min(0.6,0.08*distance)
  local vx,vz=0,0
  if distance>1e-6 then vx,vz=ex/distance*speed,ez/distance*speed end
  local sx,sz=0.045*(vx-v.x),0.045*(vz-v.z)
  local maxSlope=math.tan(math.rad(4))
  local magnitude=math.sqrt(sx*sx+sz*sz)
  if magnitude>maxSlope then sx,sz=sx*maxSlope/magnitude,sz*maxSlope/magnitude end
  -- Limit target tilt slew to avoid stepping the attitude controller.
  local dx,dz=sx-state.x,sz-state.z
  local change=math.sqrt(dx*dx+dz*dz); local limit=math.rad(1.5)*dt
  if change>limit then dx,dz=dx*limit/change,dz*limit/change end
  state.x,state.z=state.x+dx,state.z+dz
  return unit(vec(state.x,1,state.z)),distance
end
-- Height loop uses a recorded near-hover throttle, not an assumed gravity.
function M.heightStep(a,y,vy,dt,tilt,calibrationThrottle)
  assert(finite(y) and finite(vy) and finite(dt) and dt>0,"Invalid height sample")
  local feed=0
  if a.descending then
    a.target=math.max(a.floor,a.target-0.3*dt)
    if a.target<=a.floor+1e-6 then a.descending=false
    else feed=-0.3 end
  end
  local errorY=a.target-y
  local targetV=clamp(0.25*errorY+feed,-0.4,0.4)
  local errorV=targetV-vy
  local lo=math.max(0.015,calibrationThrottle*0.5,a.hover-0.6)
  local hi=math.min(15,calibrationThrottle*2,a.hover+0.6)
  local base=a.hover/math.max(0.9,math.cos(tilt))
  local raw=base+0.22*errorV+a.integral
  -- Conditional integration prevents windup at either throttle boundary.
  if (raw>=lo and raw<=hi) or (raw<lo and errorV>0) or (raw>hi and errorV<0) then
    a.integral=clamp(a.integral+0.025*errorV*dt,-0.3,0.3)
  end
  raw=base+0.22*errorV+a.integral
  -- Limit normal automatic changes to 2 percentage points per second.
  -- Emergency stop bypasses this limiter and still goes directly to zero.
  local previous=a.output or a.hover
  local output=clamp(clamp(raw,lo,hi),previous-0.3*dt,previous+0.3*dt)
  a.output=output
  a.saturated=raw<lo or raw>hi or math.abs(output-clamp(raw,lo,hi))>1e-9
  return output
end
function M.validateRecord(r,id,mass)
  assert(type(r)=="table" and r.version==2 and r.backend=="wired-output-v1","Wrong calibration backend/version; run U/K")
  assert(r.fullThrustKN==FULL_THRUST_KN and r.unitsPerKN==UNITS_PER_KN,"Saved thrust scale changed")
  assert(type(r.engines)=="table" and #r.engines==#ENGINE_NAMES,"Saved engine list changed")
  for i,name in ipairs(ENGINE_NAMES) do assert(r.engines[i]==name,"Saved engine list changed") end
  assert(r.id==id,"Saved calibration belongs to another craft")
  assert(finite(r.mass) and r.mass>0 and math.abs(mass/r.mass-1)<=0.05,"Saved mass differs >5%")
  assert(finite(r.throttle) and r.throttle>0 and r.throttle<=15,"Invalid saved throttle")
  assert(type(r.basis)=="table","Missing saved UP")
  local b={up=checked(r.basis.up),a=checked(r.basis.a),b=checked(r.basis.b)}
  for _,v in pairs(b) do assert(math.abs(norm(v)-1)<1e-5,"Invalid saved axis") end
  assert(math.abs(dot(b.up,b.a))<1e-5 and norm(add(cross(b.up,b.a),mul(b.b,-1)))<1e-5,"Invalid saved basis")
  assert(type(r.matrix)=="table","Missing saved response")
  local m=M.matrix({{r.matrix.a,r.matrix.c},{r.matrix.b,r.matrix.d}})
  return b,m
end
return M

end
local function loadfile(name)
  assert(name=="home.lua","Only embedded math is available")
  return factories.home_math
end
-- Unified experimental console. Default: read-only. No startup installation.
-- --live <config.json> explicitly initializes/zeros outputs; E separately arms.
local args={...}
local live=args[1]=="--live"
assert(not args[1] or live,"Usage: rocket_app [--live verified-config.json]")
local deps={}
for key,file in pairs({planner="recovery_plan",allocator="control_allocator",geometry="geometry_model",
  control="recovery_control",boostback="boostback_plan",mission="mission_control",
  hover="hover_control",runtime="mission_runtime"}) do deps[key]=require(file) end
deps.math=assert(loadfile("home.lua"),"Missing home.lua math module")("--test")
local config,driver,session
if live then
  assert(args[2],"Live mode requires a measured config; no default profile")
  local h=assert(fs.open(args[2],"r"),"Cannot read configuration")
  local content=h.readAll(); h.close()
  config=assert(textutils.unserializeJSON(content),"Invalid JSON configuration")
  driver=require("engine_io").new({clock=os.clock,peripheral=peripheral,redstone=redstone,
    parallel=parallel,sleep=sleep},config.caps)
  -- Validate before initialize: a rejected profile causes NO output writes.
  session=require("flight_session").new(deps,driver,config)
end
local basis=config and config.craft.basis or {up={x=0,y=1,z=0},a={x=1,y=0,z=0},b={x=0,y=0,z=-1}}
local sampler=require("telemetry").new({clock=os.clock,sublevel=sublevel,parallel=parallel,peripheral=peripheral},deps.math,basis)
local running,sample,message=true,nil,"Waiting for fresh telemetry"
local view=require("console_view")
local buttons={}
local function draw()
  buttons=view.draw(term,colors,{live=live,mode=session and session.mode,sample=sample,
    output=session and session.output,pad=session and session.pad,message=message})
end
local function producer()
  parallel.waitForAny(function()
    while running do
      local s,why=sampler:read(driver); sample=s
      if not s then
        message=why
        if session and session.mode~="DISARMED" then session:stop(why) end
      elseif session then
        local _,err=session:tick(s,os.clock()); if err then message=err end
      end
      draw(); sleep(.05)
    end
  end,function()
    local actions={[keys.j]="pad",[keys.e]="arm",[keys.r]="up",[keys.f]="down",
      [keys.v]="hover",[keys.d]="descent",[keys.b]="boostback",[keys.space]="stop"}
    while running do
      local event,key,held,y=os.pullEventRaw()
      local action
      if event=="key" and not held then action=actions[key] end
      if event=="mouse_click" and key==1 then action=view.hit(buttons,held,y) end
      if event=="terminate" or (event=="key" and key==keys.q) or action=="exit" then
        if session then session:stop("Operator exit") end
        running=false; return
      end
      if event=="term_resize" then draw() end
      if action then
        if session then
          local ok,why=session:action(action,sample,os.clock())
          message=ok and (session.message or action) or why
        else message="Read-only mode: controls disabled" end
        draw()
      end
    end
  end)
end
if live then
  print("LIVE initialization clears nine engines. No automatic ignition.")
  local ok,why=driver:initialize(); assert(ok,why)
  local cleared,errors=driver:run(producer)
  if not cleared then print("CLEANUP FAILED: "..table.concat(errors,"; ")) end
else producer() end
